css:
.card {
  max-width: 240px;
  margin: 16px;
  padding: 12px 16px;
  border: 1px solid #f97316;
  border-radius: 6px;
  background: #fed7aa;
  font-family: system-ui, sans-serif;
  overflow-wrap: anywhere;
}

.card h3 {
  margin: 0 0 8px;
}

.address {
  white-space: pre-wrap;
  color: #52525b;
}
